<?php
require __DIR__.'/../api/life/store.php';require __DIR__.'/../api/life/remember.php';
$db=new PDO('sqlite::memory:');$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$db->setAttribute(PDO::ATTR_DEFAULT_FETCH_MODE,PDO::FETCH_ASSOC);$db->exec(file_get_contents(__DIR__.'/../api/life/schema.sql'));$store=new LifeStore($db);$store->initialize('disposable-owner-password');$accounts=new LifeAccounts($db);$remember=new LifeRemember($db);$n=0;
function check($v,$message){global $n;if(!$v)throw new Exception($message);$n++;}
$a=$accounts->signUpEmail('device-a@example.test','disposable-password-one');$b=$accounts->signUpEmail('device-b@example.test','disposable-password-two');$now=1800000000;$identity=['kind'=>'user','id'=>(int)$a['id']];$cookie=$remember->issue($identity,$now);[$id,$secret]=explode('.',$cookie);
check(strlen($secret)===64,'Strong random device secret');$row=$db->query('SELECT * FROM life_device_login')->fetch();check(!str_contains(json_encode($row),$secret),'No raw secret stored');check(!str_contains(json_encode($row),'disposable-password'),'No password stored');check(strlen($row['secret_hash'])===64,'Hash stored');
$s=$remember->resume($cookie,$now+7200);check($s['userId']===$identity['id'],'Resume after old hour timeout');check($s['rememberId']===$id,'Trusted device selector');check(strlen($s['csrf'])===64,'Fresh CSRF');check($remember->resume($cookie,$now+10000)['csrf']!==$s['csrf'],'Fresh token on session recreation');check(isset($s['emailCredential']),'Credential guard preserved');
check($remember->resume($id.'.'.str_repeat('0',64),$now)===null,'Reject forged secret');check($remember->resume('malformed',$now)===null,'Reject malformed');$remember->revoke($id.'.'.str_repeat('0',64));check($remember->resume($cookie,$now)!==null,'Cannot revoke with forged secret');
$kept=$remember->keep($identity,$cookie,$now+100);check(!$kept['renew']&&$kept['cookie']===$cookie,'No duplicate per request');$kept=$remember->keep($identity,$cookie,$now+172800);check($kept['renew'],'Renew after activity');check($remember->resume($cookie,$now+LifeRemember::TTL)!==null,'Renewed server expiry');
$second=$remember->issue($identity,$now);$remember->revoke($cookie,$id);check($remember->resume($cookie,$now)===null,'Logout revokes device');check($remember->resume($second,$now)!==null,'Other device remains signed in');
$swap=$remember->keep(['kind'=>'user','id'=>(int)$b['id']],$second,$now);check($remember->resume($second,$now)===null,'Account switch revokes old device token');check($remember->resume($swap['cookie'],$now)['userId']===(int)$b['id'],'Account isolation on restore');
$changed=$remember->issue($identity,$now);$db->prepare('UPDATE life_email_auth SET password_hash=? WHERE account_id=?')->execute([password_hash('disposable-changed-password',PASSWORD_DEFAULT),$a['id']]);check($remember->resume($changed,$now)===null,'Password change invalidates saved login');
$owner=$remember->issue(['kind'=>'owner','id'=>1],$now);check($remember->resume($owner,$now)['owner']===1,'Legacy owner resumes');$google=$accounts->signIn(['sub'=>'test-google-sub','email_verified'=>true,'email'=>'google@example.test','name'=>'Fixture'],'Africa/Lagos');$gc=$remember->issue(['kind'=>'user','id'=>(int)$google['id']],$now);check($remember->resume($gc,$now)['userId']===(int)$google['id'],'Google resumes');check(!isset($remember->resume($gc,$now)['emailCredential']),'Google-only identity does not invent password');
$expired=$remember->issue(['kind'=>'user','id'=>(int)$b['id']],$now);check($remember->resume($expired,$now+LifeRemember::TTL+1)===null,'Inactive expired cookie rejected');$db->prepare('DELETE FROM life_account WHERE id=?')->execute([$google['id']]);check($remember->resume($gc,$now)===null,'Deleted account cannot resume');check(LifeRemember::identity([])===null,'Anonymous cannot get remembered');
echo "$n persistent device-login checks passed\n";
